// Config — the only node you edit. Business hours, services, staff and rules.
// Everything below this node reads its settings from here.
return [{ json: {
  "staff_chat_id": "REPLACE_WITH_TELEGRAM_CHAT_ID"
} }];

// Normalise the end-of-call report of any of the three providers into one message.
const cfg = $('Config').first().json;
const body = $('Call Ended Webhook').first().json.body || {};
const pick = (...values) => values.find((value) => value !== undefined && value !== null && value !== '');
let provider = 'unknown', summary, seconds, caller, reason, success, callId;

if (body.message && body.message.type === 'end-of-call-report') {
  const m = body.message;
  provider = 'vapi';
  summary = pick(m.summary, m.analysis && m.analysis.summary);
  seconds = pick(m.durationSeconds, m.call && m.call.durationSeconds);
  caller = m.call && m.call.customer && m.call.customer.number;
  reason = m.endedReason;
  success = m.analysis && m.analysis.successEvaluation;
  callId = m.call && m.call.id;
} else if (body.event && body.call) {
  if (body.event !== 'call_analyzed') return [];
  const c = body.call;
  provider = 'retell';
  summary = c.call_analysis && c.call_analysis.call_summary;
  seconds = c.duration_ms ? Math.round(c.duration_ms / 1000) : undefined;
  caller = c.direction === 'outbound' ? c.to_number : c.from_number;
  reason = c.disconnection_reason;
  success = c.call_analysis && c.call_analysis.call_successful;
  callId = c.call_id;
} else if (body.type && body.data) {
  if (body.type !== 'post_call_transcription') return [];
  const d = body.data;
  provider = 'elevenlabs';
  summary = d.analysis && d.analysis.transcript_summary;
  seconds = d.metadata && d.metadata.call_duration_secs;
  caller = d.metadata && d.metadata.phone_call && d.metadata.phone_call.external_number;
  reason = d.metadata && d.metadata.termination_reason;
  success = d.analysis && d.analysis.call_successful;
  callId = d.conversation_id;
} else {
  return [];
}

const minutes = seconds ? `${Math.floor(seconds / 60)}:${String(Math.round(seconds % 60)).padStart(2, '0')}` : '—';
const lines = [
  'Звонок завершён',
  `Номер: ${caller || 'не определён'}`,
  `Длительность: ${minutes}`,
  success !== undefined ? `Цель достигнута: ${success === true || success === 'true' || success === 'successful' ? 'да' : String(success)}` : '',
  reason ? `Завершение: ${reason}` : '',
  '',
  summary ? String(summary).slice(0, 900) : 'Сводка не пришла — проверьте, что у провайдера включён анализ звонка.',
].filter((line) => line !== '');
return [{ json: { provider, call_id: callId || '', staff_message: lines.join('\n'), chat_id: cfg.staff_chat_id } }];
